import {studyPage,comparisonPage,reportPage,connectResearch} from './research-ui.mjs';
import {ASPECTS,ASPECT_COLOURS,LINES,FORMS,DEFAULT_DRAFT,PRESETS,SOURCES,getLine,getForm} from './catalog.mjs';
import {resolveDamage,rawDamage,numeric,describeDamage} from './math.mjs';
import {makeBoard,adjacent,performSwap,pickProductive,loomMetrics,matchGroups,opportunities,runLoomStudy} from './loom.mjs';
import {newDraft,nextSide,draftPick,autofill,draftTeams,validateTeams} from './draft.mjs';
import {runBatch,compareConstants} from './simulation.mjs';
import {readData,writeData,clearData,importData} from './storage.mjs';
import {makeEvidence,verifyBattleReport,validateEvidence,exportCSV,textSafe,auditRules} from './evidence.mjs';
const $=(selector,root=document)=>root.querySelector(selector);
const all=(selector,root=document)=>Array.from(root.querySelectorAll(selector));
const escape=textSafe,fmt=(value,digits=1)=>Number.isFinite(value)?Number(value).toLocaleString('en-GB',{maximumFractionDigits:digits}):'n/a';
const num=(value,places=0)=>fmt(Number(value),places);
const PAGES=[{id:'study',name:'Study Desk',icon:'◉',short:'Study'},{id:'compare',name:'Compare Runs',icon:'⇄',short:'Compare'},{id:'timeline',name:'Report Timeline',icon:'≋',short:'Reports'},{id:'overview',name:'Overview',icon:'◈',short:'Overview'},{id:'damage',name:'Damage Lab',icon:'✳',short:'Damage'},{id:'loom',name:'Loom Lab',icon:'▦',short:'Loom'},{id:'draft',name:'Draft Studio',icon:'⬡',short:'Draft'},{id:'simulation',name:'Battle Simulator',icon:'◎',short:'Simulate'},{id:'experiments',name:'Balance Experiments',icon:'◫',short:'Experiments'},{id:'archive',name:'Archive Explorer',icon:'⚔',short:'Archive'},{id:'evidence',name:'Evidence & QA',icon:'⌁',short:'Evidence'},{id:'settings',name:'Settings & Sources',icon:'⚙',short:'Settings'}];
let doc=readData(),page='overview',loom=null,selectedCell=null,draft=null,archiveFilter='',archiveAspect='All',archiveForm='both',importedReport=null,comparison=null,loomStudy=null,loomBank=null,busy=false,worker=null,toastTimer=null;
function seed(){return numeric(doc.settings.seed,12345,0,4294967295)>>>0}
function preset(){return PRESETS[doc.settings.ruleset]||PRESETS['v0.2']}
function initializeEngines(){loom=makeBoard(seed(),preset());selectedCell=null;draft=newDraft(seed());loomBank={threads:0,overflow:0,bonuses:0,essence:Object.fromEntries(ASPECTS.map(a=>[a,0]))};loomStudy=null;}
initializeEngines();
function applyLoomResult(result){const available=Math.max(0,loom.rules.threadCap-loomBank.threads);const collected=Math.min(available,result.threads);loomBank.threads+=collected;loomBank.overflow+=result.threads-collected;loomBank.bonuses+=Number(result.bonus);for(const a of ASPECTS)loomBank.essence[a]+=result.essence[a]||0;}
function store(){try{writeData(doc)}catch{toast('Unable to save to this browser. Export a backup.',true)}}
function toast(message,error=false){const el=$('#toast');el.hidden=false;el.textContent=message;el.style.background=error?'#57313d':'#234e54';clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.hidden=true},3900)}
function download(name,content,type='application/json'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function addEvidence(kind,settings,output,source='synthetic'){const evidence=makeEvidence({kind,settings,output,source,ruleset:doc.settings.ruleset,notes:doc.settings.notes||''});doc.evidence.unshift(evidence);doc.evidence=doc.evidence.slice(0,100);store();return evidence}
const chip=(label,cls='')=>`<span class="chip ${cls}">${escape(label)}</span>`;
const aspect=(value)=>`<span class="aspect" style="--aspect:${ASPECT_COLOURS[value]||'#93c5fd'}">${escape(value)}</span>`;
const metric=(title,value,desc,color='cyan')=>`<div class="metric"><span class="small">${escape(title.toUpperCase())}</span><strong class="${color}">${escape(value)}</strong><p>${escape(desc)}</p></div>`;
const statbox=(value,label)=>`<div class="stat-box"><b>${escape(value)}</b><span>${escape(label)}</span></div>`;
const field=(id,label,value,{type='number',min=null,max=null,step=1,placeholder='',extra=''}={})=>`<div class="field"><label for="${id}">${escape(label)}</label><input id="${id}" type="${type}" value="${escape(value)}" ${min!==null?`min="${min}"`:''} ${max!==null?`max="${max}"`:''} step="${step}" placeholder="${escape(placeholder)}" ${extra}></div>`;
const select=(id,label,options,value)=>`<div class="field"><label for="${id}">${escape(label)}</label><select id="${id}">${options.map(([v,t])=>`<option value="${escape(v)}" ${String(value)===String(v)?'selected':''}>${escape(t)}</option>`).join('')}</select></div>`;
const formOptions=FORMS.map(f=>[f.id,`${f.name} (${f.aspect})`]);
const row=(name,desc,icon,action)=>`<div class="workspace-item"><div class="square">${icon}</div><div><strong>${escape(name)}</strong><p>${escape(desc)}</p></div><button class="button secondary right" type="button" data-page="${action}" aria-label="Open ${escape(name)}">↗</button></div>`;
function renderNav(){const nav=PAGES.map((p,i)=>`<button type="button" class="nav-link ${page===p.id?'active':''}" data-page="${p.id}"><span class="symbol">${p.icon}</span><span>${p.name}</span><span class="index">${String(i+1).padStart(2,'0')}</span></button>`).join('');$('#desktopNav').innerHTML=nav;
 const mobile=['overview','study','loom','simulation','settings'].map(id=>{const p=PAGES.find(x=>x.id===id);return `<button class="${page===id?'active':''}" type="button" data-page="${id}"><span class="symbol">${p.icon}</span>${p.short}</button>`}).join('');$('#mobileNav').innerHTML=mobile;$('#currentPage').textContent=PAGES.find(x=>x.id===page)?.name||'Overview';$('#ruleset').value=doc.settings.ruleset;}
const heroArt=`<svg class="hero-art" viewBox="0 0 250 250" role="img" aria-label="Illustrated Weave combat lattice" xmlns="http://www.w3.org/2000/svg"><g fill="none" stroke="#557895" stroke-width="1.5"><path d="M125 15 226 69v112L125 237 24 181V69Z"/><path d="M125 55 190 90v70l-65 35-65-35V90Z"/><path d="M125 15v222M24 69l202 112M226 69 24 181" opacity=".75"/></g><path d="m125 56 65 69-65 69-65-69Z" fill="#132737" stroke="#87dcf4" stroke-width="3"/><circle cx="125" cy="125" r="21" fill="#103242" stroke="#9ceaf3" stroke-width="3"/><path d="m125 106 15 19-15 19-15-19Z" fill="#78deed"/><g><circle cx="125" cy="15" r="5" fill="#5ebaf9"/><circle cx="226" cy="69" r="5" fill="#f48c78"/><circle cx="226" cy="181" r="5" fill="#c6a46a"/><circle cx="125" cy="237" r="5" fill="#b4a3f6"/><circle cx="24" cy="181" r="5" fill="#8ee0a3"/><circle cx="24" cy="69" r="5" fill="#bf91df"/></g></svg>`;
function overview(){const p=preset();return `<section class="hero"><div><div class="eyebrow">COMBAT SYSTEMS / RESEARCH ENVIRONMENT</div><h1>Balance the battle.<br><span>Prove the change.</span></h1><p>Explore damage, manipulate the 7×7 Loom, draft all six canonical lines and measure seeded synthetic Battles. Built for rigorous iteration, not unverified claims.</p><div class="hero-actions"><button class="button primary" data-page="simulation">◎ Run simulations</button><button class="button secondary" data-page="archive">⚔ Explore the Archive</button></div></div>${heroArt}</section>
 <div class="metric-grid">${metric('Archive forms','12','6 Base + 6 Rewoven')}${metric('Shared Loom','7 × 7','49 Strands','purple')}${metric('Turn economy','2 moves','A 4+ Weave grants one Bonus','amber')}${metric('Reweaving',`${p.threadCost} Threads`,`${p.id} · cap ${p.threadCap}`)}</div>
 <div class="two-col"><section class="panel"><div class="panel-title">Research workspaces ${chip('Eleven research workspaces','green')}</div>
 ${row('Controlled Study Desk','1,000-trial schedule, SHA-256 manifests and engine readiness','◉','study')}
 ${row('Compare Runs','Paired seed comparisons across exported batches','⇄','compare')}
 ${row('Report Timeline','Search source events without changing the report','≋','timeline')}
 ${row('Damage Workbench','Physical vs Special, True Damage, Shield interactions and AP calibration','⚔','damage')}
 ${row('Loom Mechanics','Seeded swaps, intersecting Weaves, Cascades and Threads','▦','loom')}
 ${row('Draft Studio','Exclusive six-line snake draft and independently chosen initiative','⬡','draft')}
 ${row('Monte Carlo Simulator','Repeatable synthetic policy battles and Wilson intervals','◎','simulation')}
 ${row('Sensitivity Experiments','Controlled Defence constants, AP and resource parameters','◫','experiments')}
 ${row('Evidence & QA','Versioned experiment exports, report inspection and coverage','⌁','evidence')}
 </section><section class="panel"><div class="panel-title">Ruleset integrity ${chip('Version-aware','purple')}</div>
 <div class="notice blue" style="margin-top:0"><strong>One important distinction:</strong> the released v0.1.2 engine has one Defence and six-Thread Reweaving. The approved v0.2 design separates Physical/Special Defence and speeds up the Thread economy. The Lab never silently merges these rules.</div>
 <div class="info-grid" style="margin-top:16px"><div class="info-mini"><small>APPROVED DAMAGE</small><strong>AP × ATK / (50 + DEF)</strong><p>v0.2 trial formula</p></div><div class="info-mini"><small>RAPID REWEAVING</small><strong>4 Threads + 1 Move</strong><p>6-Thread held cap</p></div><div class="info-mini"><small>LOOM REFILL</small><strong>35% marker chance</strong><p>14 Loom-marker cap</p></div><div class="info-mini"><small>BATTLE TARGET</small><strong>8–10 minutes</strong><p>Aspirational, not proven</p></div></div>
 <div class="divider"></div><div class="tiny">Canonical sources: <a target="_blank" rel="noreferrer" href="${SOURCES.combat}">Combat System ↗</a> · <a href="${SOURCES.balance}" target="_blank" rel="noreferrer">Balance Constants ↗</a></div></section></div>
 <div class="notice"><strong>Evidence standard:</strong> a synthetic match result is not equivalent to a Weave Battle Report. Use this Lab to design experiments, then verify conclusions with the actual engine and live playtests. No automatic changes to canonical rules, stats or files.</div>`;}
function damage(){const cfg=doc.settings,attacker=FORMS.find(x=>x.id===cfg.formA)||FORMS[9],target=FORMS.find(x=>x.id===cfg.formB)||FORMS[3],legacy=cfg.ruleset==='v0.1.2';const physical=cfg.mode==='physical',def=legacy?numeric(cfg.legacyDef,100,0,9999):physical?target.phy:target.spe,attack=legacy?numeric(cfg.legacyAtk,100,0,9999):attacker.atk,hp=legacy?numeric(cfg.legacyHp,130,1,9999):target.hp;
 const result=resolveDamage({ap:numeric(cfg.ap,40,0,1000),atk:attack,def,shield:numeric(cfg.shield,0,0,10000),hp,trueDamage:cfg.trueDamage,immune:target.lineId==='craglet',critical:cfg.critical,mode:cfg.ruleset,constant:numeric(cfg.constant,50,1,500)});
 const ranges=[['Setup / weak',8,15],['Standard',15,25],['Strong',25,35],['Finisher',35,45]];
 return `<div class="page-top"><div class="eyebrow">01 / COMBAT MATHEMATICS</div><h1>Damage Lab</h1><p>Isolate Ability Power (AP), Attack (ATK), defence, Shield and True Damage. Compare the frozen v0.1.2 formula against the approved v0.2 split-defence model. All hypothetical tuning values are temporary.</p></div>
 <div class="two-col"><section class="panel"><div class="panel-title">Attack scenario ${chip(doc.settings.ruleset==='v0.2'?'v0.2 formula':'Legacy formula','purple')}</div><div class="form-grid">
 ${legacy?`${field('legacyAtk','Hypothetical legacy Attack',attack,{min:0,max:9999})}${field('legacyDef','Hypothetical single Defence',def,{min:0,max:9999})}${field('legacyHp','Hypothetical target HP',hp,{min:1,max:9999})}`:`${select('damageA','Attacking Weaver',formOptions,cfg.formA)}${select('damageB','Defending Weaver',formOptions,cfg.formB)}`}
 ${field('damageAP','Art Ability Power',cfg.ap,{min:0,max:1000})}${field('damageShield','Defender Shield',cfg.shield,{min:0,max:10000})}
 ${select('damageType','Damage category',[['physical','Physical'],['special','Special']],cfg.mode)}${field('damageConstant','Defence smoothing constant',cfg.constant,{min:1,max:500,extra:doc.settings.ruleset==='v0.1.2'?'disabled':''})}
 <div class="field full"><label>Properties</label><div class="control-line"><label class="checkfield"><input id="damageTrue" type="checkbox" ${cfg.trueDamage?'checked':''}> True Damage (Shield bypass)</label><label class="checkfield"><input id="damageCrit" type="checkbox" ${cfg.critical?'checked':''}> Critical ×1.5</label></div></div></div>
 <div class="notice blue"><strong>Attack:</strong> ${attack} ATK. <strong>Defence:</strong> ${fmt(def,0)} ${legacy?'hypothetical single DEF':physical?'PHY.DEF':'SP.DEF'}. ${legacy?'Legacy numbers are hypothetical, not the current Archive roster.':target.lineId==='craglet'?'Craglet/Cragkyl immunity converts True Damage into normal damage for Shield.':''}</div>
 <div class="control-line" style="margin-top:14px"><button class="button primary" data-action="save-damage">Save evidence</button><button class="button secondary" data-action="export-damage">Export calculation</button></div></section>
 <section class="panel"><div class="panel-title">Resolved hit ${chip(describeDamage(result.pctHp),'green')}</div><div class="result-head"><strong class="cyan">${fmt(result.hpDamage,0)}</strong><span class="subtle">HP damage / ${hp} max HP</span></div><div class="bar-track" style="height:13px;margin:12px 0"><div class="bar-fill" style="width:${Math.min(100,result.pctHp)}%"></div></div>
 <div class="stat-strip">${statbox(result.raw,'Pre-Shield damage')}${statbox(result.shieldAbsorbed,'Shield absorbed')}${statbox(`${fmt(result.pctHp)}%`,'Target max HP')}</div>
 <div class="info-grid" style="margin-top:14px"><div class="info-mini"><small>REMAINING HP</small><strong>${result.remainingHp}</strong></div><div class="info-mini"><small>REMAINING SHIELD</small><strong>${result.remainingShield}</strong></div><div class="info-mini"><small>TRUE DAMAGE</small><strong>${result.convertedTrue?'Converted by immunity':result.bypassesShield?'Bypasses Shield':'Normal interaction'}</strong></div><div class="info-mini"><small>HYPOTHETICAL ARTS TO KO</small><strong>${result.hpDamage?Math.ceil(hp/result.hpDamage):'∞'}</strong><p>Static repetition only</p></div></div><p style="font-size:11px">Raw damage is rounded to the nearest integer before Shield. Repeated-Art KO estimates ignore Essence, target response and changing states.</p></section></div>
 <div class="two-col"><section class="panel"><div class="panel-title">Controlled Defence smoothing</div><p>Compare constants without changing the approved formula structure. Values are illustrative sensitivity cases.</p><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Constant</th><th>Raw hit</th><th>HP damage</th><th>% of target HP</th></tr></thead><tbody>${[40,50,65].map(c=>{const x=resolveDamage({ap:numeric(cfg.ap,40,0,1000),atk:attack,def,shield:numeric(cfg.shield,0,0,10000),hp,trueDamage:cfg.trueDamage,immune:target.lineId==='craglet',critical:cfg.critical,constant:c,mode:cfg.ruleset});return `<tr><td>${c}</td><td>${x.raw}</td><td>${x.hpDamage}</td><td>${fmt(x.pctHp)}%</td></tr>`}).join('')}</tbody></table></div></section>
 <section class="panel"><div class="panel-title">Provisional damage bands</div>${ranges.map(([name,min,max])=>`<div style="margin-bottom:10px"><div class="control-line" style="justify-content:space-between;font-size:11px;margin-bottom:4px"><span>${name}</span><span class="subtle">${min}–${max}% max HP</span></div><div class="bar-track"><div class="bar-fill" style="margin-left:${min}%;width:${max-min}%;background:${name==='Finisher'?'var(--amber)':'var(--cyan)'}"></div></div></div>`).join('')}<p>These are balance guidance bands, not strict damage caps. Multi-hit, setup, Shield, statuses and defensive roles must be tested separately.</p></section></div>`;
}
const STRAND_SYMBOL={Aqua:'◆',Ignis:'✦',Terra:'⬡',Sky:'✶',Wild:'✿',Aether:'✧'};
function loomPage(){const m=loomMetrics(loom);return `<div class="page-top"><div class="eyebrow">02 / MATCH-THREE SYSTEMS</div><h1>Loom Lab</h1><p>A seeded 7×7 editor with genuine adjacent swapping, connected cross-shaped Weave groups, gravity, Cascades, Threads and dead-Loom reshuffles. Tapping a Strand and an adjacent neighbour commits a Move, even if no Weave is created.</p></div>
 <div class="two-col"><section class="panel"><div class="panel-title">Interactive shared Loom ${chip('Seed '+seed(),'purple')}</div><div class="loom" role="group" aria-label="7 by 7 Loom board">${loom.board.map((cell,i)=>`<button type="button" class="strand ${cell.thread?'thread':''} ${selectedCell===i?'selected':''}" data-cell="${i}" style="--strand:${ASPECT_COLOURS[cell.aspect]}" aria-label="${cell.aspect}${cell.thread?' with Thread Marker':''}, row ${Math.floor(i/7)+1}, column ${i%7+1}">${STRAND_SYMBOL[cell.aspect]}</button>`).join('')}</div>
 <div class="control-line" style="justify-content:center"><button class="button primary" data-action="loom-auto">✳ Best productive swap</button><button class="button secondary" data-action="loom-reset">↻ Reset seed</button><button class="button secondary" data-action="loom-export">↓ Snapshot</button></div>
 <p style="text-align:center;font-size:11px">Developer-only suggested swap, never shown in the competitive game.</p></section><section class="stack"><section class="panel"><div class="panel-title">Loom telemetry</div><div class="stat-strip">${statbox(m.step,'Moves played')}${statbox(m.markers,'Thread Markers')}${statbox(m.opportunities,'Weave opportunities')}</div><div class="stat-strip" style="margin-top:10px">${statbox(loomBank.threads+'/'+loom.rules.threadCap,'Held Threads')}${statbox(loomBank.bonuses,'Bonus Moves')}${statbox(loomBank.overflow,'Wasted Threads')}</div><div class="control-line" style="margin-top:12px"><button class="button secondary" data-action="loom-reweave" ${loomBank.threads<loom.rules.threadCost?'disabled':''}>Spend ${loom.rules.threadCost} Threads on synthetic Reweave</button></div><div class="divider"></div>${ASPECTS.map(a=>`<div style="display:grid;grid-template-columns:75px 1fr 25px;align-items:center;gap:10px;margin:10px 0">${aspect(a)}<div class="bar-track"><div class="bar-fill" style="width:${m.aspectCount[a]/49*100}%;background:${ASPECT_COLOURS[a]}"></div></div><span class="tiny">${m.aspectCount[a]}</span></div>`).join('')}</section><section class="panel"><div class="panel-title">Versioned Thread economy</div><div class="info-grid"><div class="info-mini"><small>REWEAVE COST</small><strong>${loom.rules.threadCost} Threads</strong></div><div class="info-mini"><small>STARTING MARKERS</small><strong>${loom.rules.startingMarkers}</strong></div><div class="info-mini"><small>REFILL CHANCE</small><strong>${Math.round(loom.rules.markerChance*100)}%</strong></div><div class="info-mini"><small>POST-MOVE FLOOR / CAP</small><strong>${loom.rules.markerFloor} / ${loom.rules.markerCap}</strong></div></div></section></section></div>
 <div class="two-col"><section class="panel"><div class="panel-title">Recent resolution log</div>${loom.history.length?loom.history.slice(-8).reverse().map(v=>`<div class="log-row">Move ${v.step}: #${v.a+1} → #${v.b+1} · ${v.strands} Strands · ${v.threads} Threads · ${v.cascades} Cascade steps ${v.bonus?chip('+1 Bonus','green'):''}</div>`).join(''):'<p class="empty">No swaps yet. Start by tapping two adjacent Strands.</p>'}</section><section class="panel"><div class="panel-title">Mechanics fidelity</div><p>Starting boards have no automatic Weaves but at least one productive swap. Matches combine intersecting lines by unique Strand identity. Every removed Strand awards resources exactly once. Gravity and refill repeat to a stable Loom.</p><div class="notice blue"><strong>Important limit:</strong> this board models core Loom rules, not Weaver-specific shifts, conversions or special Strands. Automatic developer swap suggestions are for balance analysis only.</div></section></div><section class="panel" style="margin-top:15px"><div class="panel-title">Seed bank / Loom-only Monte Carlo ${chip('Developer tool','purple')}</div><p>Evaluate 100 independently seeded Looms over 20 productive swaps each, recording Bonus rates, Cascade intensity and Threads. This does not model combat, players or real match length.</p><div class="control-line"><button class="button primary" data-action="loom-study" ${busy?'disabled':''}>Run 100-seed study</button><button class="button secondary" data-action="loom-study-export" ${loomStudy?'':'disabled'}>Export study JSON</button></div>${loomStudy?`<div class="result-grid" style="margin-top:14px">${statbox(fmt(loomStudy.metrics.bonusRate*100,1)+'%','Bonus Move rate')}${statbox(fmt(loomStudy.metrics.meanThreadsPerMove,2),'Threads / swap')}${statbox(fmt(loomStudy.metrics.meanCascadesPerMove,2),'Cascade steps / swap')}${statbox(loomStudy.metrics.lowestMarkers+'–'+loomStudy.metrics.highestMarkers,'Marker range')}</div>`:''}</section>`;}
function draftPage(){const side=nextSide(draft),teams=[0,1].map(s=>draft.picks.filter(x=>x.side===s).map(p=>p.id));return `<div class="page-top"><div class="eyebrow">03 / ROSTER STRATEGY</div><h1>Draft Studio</h1><p>Practice the exclusive A–B–B–A–A–B snake draft. Each species line can be selected only once across both teams. The first Battle player is chosen independently of the first drafter.</p></div>
 <div class="two-col"><section class="panel"><div class="panel-title">Available species lines ${chip(draft.cursor===6?'Draft complete':`Pick ${draft.cursor+1} of 6`,'green')}</div><p>First draft picker: Player ${draft.firstPick+1}. Independent first Battle Turn: Player ${draft.firstBattleTurn+1}. ${side!==null?`Currently drafting: Player ${side+1}.`:'All species drafted.'}</p><div class="draft-pool">${LINES.map(line=>`<button class="draft-option" type="button" data-pick="${line.id}" ${draft.picks.some(p=>p.id===line.id)?'disabled':''}><span class="logo" style="color:${ASPECT_COLOURS[line.aspect]}">${line.icon}</span><strong>${escape(line.forms[0].name)} → ${escape(line.forms[1].name)}</strong>${aspect(line.aspect)}<span class="tiny">${escape(line.role)}</span></button>`).join('')}</div>
 <div class="control-line" style="margin-top:16px"><button class="button primary" data-action="draft-auto" ${draft.cursor===6?'disabled':''}>Auto-complete</button><button class="button secondary" data-action="draft-reset">New seeded draft</button><button class="button secondary" data-action="draft-to-sim" ${draft.cursor<6?'disabled':''}>Use in Simulator ↗</button></div></section>
 <section class="panel"><div class="panel-title">Live team composition</div>${[0,1].map((s)=>`<div style="padding:14px;margin-bottom:12px;border:1px solid var(--stroke);border-radius:11px"><strong>Player ${s+1}</strong>${chip(teams[s].length+'/3 picks')}<div class="team-row">${teams[s].map(id=>{const l=getLine(id);return `<span class="team-token">${escape(l.forms[0].name)} ${aspect(l.aspect)}</span>`}).join('')||'<span class="tiny">No selections yet</span>'}</div></div>`).join('')}
 <div class="panel-title" style="margin-top:15px">Snake order</div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Pick</th><th>Team</th><th>Selection</th></tr></thead><tbody>${Array.from({length:6},(_,i)=>{const pick=draft.picks[i];return `<tr><td>${i+1}</td><td>Player ${(draft.firstPick+[0,1,1,0,0,1][i])%2+1}</td><td>${pick?escape(getLine(pick.id).forms[0].name):'Waiting'}</td></tr>`}).join('')}</tbody></table></div>
 <div class="notice blue">Draft ordering is enforced, but this Lab does not implement timed 10-second picks or the real networked draft protocol.</div></section></div>`;}
function simConfig(){let teams=DEFAULT_DRAFT;if(draft.cursor===6){try{teams=draftTeams(draft)}catch{}}
return {seed:seed(),runs:numeric(doc.settings.simRuns,100,1,1000),ruleset:doc.settings.ruleset,policyA:doc.settings.policyA,policyB:doc.settings.policyB,constant:numeric(doc.settings.constant,50,1,500),apScale:numeric(doc.settings.apScale??1,1,0.2,3),teams,maxMoves:400};}
const POLICIES=[['balanced','Balanced'],['aggressive','Aggressive'],['economy','Essence efficient'],['control','Control / varied']];
function resultPanel(){const r=doc.lastBatch;if(r&&r.settings.ruleset!==doc.settings.ruleset)return `<div class="empty">Batch evidence belongs to a different ruleset. Switch back to ${escape(r.settings.ruleset)} to inspect it.</div>`;if(!r)return `<div class="empty"><strong>No batch results yet</strong><p>Run a seeded synthetic policy batch. Every result is marked model-only evidence.</p></div>`;
 const s=r.stats,win=s.winRateA===null?'N/A':fmt(s.winRateA*100,1)+'%',int=s.wilsonA?`${fmt(s.wilsonA.lower*100,1)}–${fmt(s.wilsonA.upper*100,1)}%`:'N/A';return `<div class="result-head"><strong class="cyan">${win}</strong><span class="subtle">Player A win rate among non-draw completed matches</span></div><p class="tiny">Wilson 95% interval: ${int}. Sample size ${s.runs}. Unfinished: ${s.unfinished}. Results depend on artificial decision policies.</p>
 <div class="result-grid">${statbox(fmt(s.meanMoves,1),'Mean Moves')}${statbox(fmt(s.meanBonus,1),'Bonus / match')}${statbox(fmt(s.meanCascades,1),'Cascade steps')}${statbox(fmt(s.meanTurns,1),'Mean Turns')}${statbox(fmt(s.meanReweavesA,2),'P1 Reweaves')}${statbox(fmt(s.meanReweavesB,2),'P2 Reweaves')}${statbox(fmt(s.meanEssence,1),'Essence gained')}${statbox(s.unfinished,'Move-capped')}</div>
 <div class="comparison-bars">${[['Player A',s.winsA],['Player B',s.winsB],['Draw',s.draws],['Unfinished',s.unfinished]].map(([label,v],i)=>`<div class="compare-item"><div class="vertical"><div class="fill" style="height:${Math.max(3,Math.round((v/s.runs)*100))}%;background:${['var(--cyan)','var(--purple)','var(--amber)','var(--muted)'][i]}"></div></div><strong>${v}</strong><br><small>${label}</small></div>`).join('')}</div>
 <div class="control-line"><button class="button primary" data-action="sim-evidence">Save evidence</button><button class="button secondary" data-action="sim-csv">Export matches CSV</button><button class="button secondary" data-action="sim-json">Export batch JSON</button></div>`;}
function simulatorPage(){const c=simConfig();return `<div class="page-top"><div class="eyebrow">04 / MONTE CARLO</div><h1>Battle Simulator</h1><p>Run repeated seeded synthetic 3v3 matches in a dedicated worker. Compare tactical policy choices and resource economy without claiming the output reproduces the complete Weave combat engine.</p></div>
 <div class="two-col"><section class="panel"><div class="panel-title">Simulation parameters ${chip('Synthetic model','purple')}</div><div class="form-grid">
 ${field('simSeed','Starting seed',seed(),{min:0,max:4294967295})}${select('simRuns','Number of matches',[[10,'10 · smoke'],[50,'50 · explore'],[100,'100 · baseline'],[250,'250 · comparative'],[500,'500 · extended']],c.runs)}
 ${select('policyA','Player A policy',POLICIES,c.policyA)}${select('policyB','Player B policy',POLICIES,c.policyB)}
 ${field('simAPScale','Experimental Art AP multiplier',c.apScale,{min:.2,max:3,step:.05})}${field('simConstant','Defence constant',c.constant,{min:1,max:500,extra:c.ruleset==='v0.1.2'?'disabled':''})}
 </div><div class="divider"></div><strong>Exclusive teams</strong><div class="team-row">${c.teams.map((team,i)=>`<div class="info-mini" style="flex:1"><small>PLAYER ${i+1}</small>${team.map(id=>`<div class="tiny">${escape(getLine(id)?.forms[0].name||id)}</div>`).join('')}</div>`).join('')}</div><div class="control-line" style="margin-top:14px"><button class="button primary" ${busy||c.ruleset==='v0.1.2'?'disabled':''} data-action="sim-run">◎ ${c.ruleset==='v0.1.2'?'v0.2 required':busy?'Running…':'Run seeded batch'}</button><button class="button secondary" data-page="draft">Edit draft ↗</button></div>
 <div class="notice blue">${c.ruleset==='v0.1.2'?'<strong>Legacy guardrail:</strong> v0.1.2 synthetic full-roster simulations are disabled. Its released engine has temporary kits, not the current 12-form Archive. Select v0.2 to experiment.<br><br>':''}<strong>Simulation assumptions:</strong> simplified Art selection, targeting and combat. Human match duration is not inferred from action counts. No complete status, trait, reactive chain, conditional AP or live opponent AI logic. The actual engine is the acceptance authority.</div></section>
 <section class="panel"><div class="panel-title">Batch analytics ${chip(doc.lastBatch?'Recorded':'Waiting',doc.lastBatch?'green':'')}</div>${resultPanel()}</section></div>`;}
function experimentPage(){return `<div class="page-top"><div class="eyebrow">05 / SENSITIVITY ANALYSIS</div><h1>Balance Experiments</h1><p>Explore how planned tuning variables influence a controlled synthetic match sample. Every comparison runs common seeds (paired-seed design) rather than mixing independent random samples.</p></div>
 <div class="two-col"><section class="panel"><div class="panel-title">Defence smoothing study</div><p>Preserve the approved AP × ATK / (50 + relevant DEF) formula structure while varying the constant between 40, 50 and 65 as an experiment. These are not automatic rule changes.</p><div class="form-grid">${field('experimentSeed','Starting seed',seed(),{min:0,max:4294967295})}${select('experimentRuns','Matches per condition',[[10,'10'],[50,'50'],[100,'100'],[250,'250']],Math.min(250,doc.settings.experimentRuns||50))}</div><div class="control-line" style="margin-top:15px"><button class="button primary" ${busy||doc.settings.ruleset==='v0.1.2'?'disabled':''} data-action="experiment-run">◫ Compare constants</button><button class="button secondary" data-action="experiment-export" ${comparison?'':'disabled'}>Export experiment</button></div><div class="notice blue"><strong>Design:</strong> same draft and seed range per condition. Compare directional sensitivity, not proof of PvP balance.</div></section><section class="panel"><div class="panel-title">Comparison results</div>${comparison?`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Constant</th><th>Mean Moves</th><th>P1 Win%</th><th>Reweaves</th><th>Unfinished</th></tr></thead><tbody>${comparison.map(r=>`<tr><td>${r.constant}</td><td>${fmt(r.summary.meanMoves,1)}</td><td>${r.summary.winRateA===null?'N/A':fmt(r.summary.winRateA*100,1)+'%'}</td><td>${fmt(r.summary.meanReweavesA+r.summary.meanReweavesB,2)}</td><td>${r.summary.unfinished}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Run a paired-seed experiment to compare models.</div>'}
 <div class="divider"></div><strong>Experimental guardrails</strong><p>Keep AP and roster stats fixed when comparing Defence smoothing. Run other sweeps separately. Track tradeoffs: match length, fragile Weaver survivability, signature-Art access and tank stalemates.</p></section></div>
 <div class="two-col"><section class="panel"><div class="panel-title">Approved tuning levers</div>${[['Art Ability Power','Primary damage lever; avoid a new global multiplier'],['Defence smoothing','40 / 50 / 65 sensitivity; 50 remains provisional'],['Threads & marker economy','4 cost, 8 start, 14 cap, 35% refill in approved trial'],['Signature-Art access','Measure Essence affordability and opportunity cost'],['Rewoven opportunity','Six Reweaves by minute six is aspirational, not forced']].map(([a,b])=>`<div class="workspace-item"><div class="square">◈</div><div><strong>${a}</strong><p>${b}</p></div></div>`).join('')}</section><section class="panel"><div class="panel-title">Results are not verdicts</div><p>Do not adjust canonical stats from a synthetic policy alone. Use exact engine regressions, seeded Battle Reports, per-kit QA and actual player experience before approving a change.</p><div class="notice"><strong>Release gate:</strong> only approved changes can enter the Weave codebase. Weave Lab never rewrites game files or Linear tickets without an explicit follow-up task.</div></section></div>`;}
function archivePage(){let forms=FORMS.filter(f=>(archiveForm==='both'||(archiveForm==='base'?!f.rewoven:f.rewoven))&&(archiveAspect==='All'||f.aspect===archiveAspect)&&(`${f.name} ${f.aspect} ${f.role} ${f.trait}`.toLowerCase().includes(archiveFilter.toLowerCase())));
 return `<div class="page-top"><div class="eyebrow">06 / CANONICAL ARCHIVE</div><h1>Archive Explorer</h1><p>Inspect all 12 approved first-generation forms. HP, ATK, Physical Defence, Special Defence, Essence Capacity and Art numbers are provisional playtest values, linked to their current Archive pages.</p></div>
 <div class="search-row"><input id="archiveSearch" type="search" placeholder="Search species, Trait or role" aria-label="Search Archive" value="${escape(archiveFilter)}"><select id="archiveAspect" aria-label="Filter by Aspect">${['All',...ASPECTS].map(a=>`<option ${a===archiveAspect?'selected':''}>${a}</option>`).join('')}</select><select id="archiveForm" aria-label="Filter by form"><option value="both" ${archiveForm==='both'?'selected':''}>Both forms</option><option value="base" ${archiveForm==='base'?'selected':''}>Base only</option><option value="rewoven" ${archiveForm==='rewoven'?'selected':''}>Rewoven only</option></select></div>
 <div class="form-list">${forms.map(f=>`<article class="form-card"><div class="head">${aspect(f.aspect)}${chip(f.rewoven?'Rewoven':'Base',f.rewoven?'purple':'')}</div><h3>${escape(f.name)}</h3><p>${escape(f.role)} · ${escape(f.trait)}</p><div class="stats"><span><strong>${f.hp}</strong> HP</span><span><strong>${f.atk}</strong> ATK</span><span><strong>${f.essence}</strong> ESS</span><span><strong>${f.phy}</strong> PHY.DEF</span><span><strong>${f.spe}</strong> SP.DEF</span><span><strong>${f.rewoven?'II':'I'}</strong> FORM</span></div><div class="divider"></div><strong style="font-size:11px">Fixed Arts</strong>${f.arts.map(a=>`<div class="art-line"><div><strong>${escape(a.name)}</strong><small>${escape(a.effect)}</small></div><div class="ap">${a.cost} E${a.power?`<br>${a.power} AP`:''}</div></div>`).join('')}<a href="${f.source}" target="_blank" rel="noreferrer">Canonical Archive entry ↗</a></article>`).join('')||'<div class="empty">No matching Weaver forms.</div>'}</div>`;}
function evidencePage(){return `<div class="page-top"><div class="eyebrow">07 / PROVENANCE & VERIFICATION</div><h1>Evidence & QA</h1><p>Keep synthetic research separate from exact in-game Battle Reports. Inspect report structure, save reproducible settings and export versioned evidence for reviews.</p></div>
 <div class="two-col"><section class="panel"><div class="panel-title">Import a Weave Battle Report</div><p>Paste a report exported by the actual Weave game. The Lab checks its schema and summarises actions; it does not replay or cryptographically authenticate its contents.</p><div class="field"><label for="reportJSON">Weave Battle Report JSON</label><textarea id="reportJSON" placeholder='{"schemaVersion":1,"weaveVersion":"0.1.2", ...}' spellcheck="false"></textarea></div><div class="control-line" style="margin-top:12px"><button class="button primary" data-action="report-parse">Inspect report</button><button class="button secondary" data-action="report-file">Choose JSON file</button><input id="reportFile" hidden type="file" accept=".json,application/json"></div>
 ${importedReport?`<div class="divider"></div><div class="stat-strip">${statbox(importedReport.turnCount,'Turns')}${statbox(importedReport.actions,'Actions')}${statbox(importedReport.eventCounts.bonusMove,'Bonus Events')}</div><p>Seed ${importedReport.seed} · Game version ${escape(importedReport.weaveVersion)} · Result ${escape(importedReport.result)}</p>${importedReport.warnings.map(x=>`<p class="amber">⚠ ${escape(x)}</p>`).join('')}<button class="button primary" data-action="report-evidence">Save report metadata</button>`:''}
 </section><section class="panel"><div class="panel-title">Evidence registry ${chip(`${doc.evidence.length} records`,'green')}</div>${doc.evidence.length?doc.evidence.slice(0,10).map(x=>`<div class="workspace-item"><div class="square">◈</div><div><strong>${escape(x.kind)} · ${escape(x.ruleset)}</strong><p>${escape(x.recordedAt)} · ${escape(x.model)}</p><p>Checksum ${escape(x.checksum||'unknown')}</p></div><button class="button secondary right" data-evidence="${escape(x.checksum)}">Export ↗</button></div>`).join(''):'<div class="empty">No saved research yet. Use a workbench to record an experiment.</div>'}<div class="control-line"><button class="button secondary" data-action="evidence-all">Export registry</button><button class="button secondary" data-action="evidence-csv">Export summary CSV</button></div></section></div>
 <div class="two-col"><section class="panel"><div class="panel-title">Ruleset coverage matrix</div>${auditRules().map(x=>`<div class="qa-item"><span>✳</span><div>${escape(x.rule)}<div class="tiny">${escape(x.versions)}</div></div><span class="tag">${chip(x.status,x.status==='approved'?'green':x.status==='aspirational'?'amber':'purple')}</span></div>`).join('')}</section><section class="panel"><div class="panel-title">Evidence maturity ladder</div>${[['1. Formula check','Deterministic local mathematics; exact only for declared simplifications'],['2. Synthetic simulation','Model behaviour, seeded policy choices, directional hypotheses'],['3. Actual game report','Real engine actions with engine revision and ruleset fingerprint'],['4. Replay & regression','Run the exact game engine with report inputs; independent parity tests'],['5. Human playtest','Multiple players, observed pacing, strategic satisfaction, UX findings']].map(([a,b])=>`<div class="workspace-item"><div class="square">✓</div><div><strong>${a}</strong><p>${b}</p></div></div>`).join('')}</section></div>`;}
function settingsPage(){const p=preset();return `<div class="page-top"><div class="eyebrow">08 / CONTROL PLANE</div><h1>Settings & Sources</h1><p>Version selection, reproducibility, export/restore, limitations and direct links to the current game-design sources.</p></div>
 <div class="two-col"><section class="panel"><div class="panel-title">Ruleset profile</div><div class="form-grid">${select('settingsRuleset','Ruleset',Object.values(PRESETS).map(p=>[p.id,p.label]),doc.settings.ruleset)}${field('settingsSeed','Research seed',seed(),{min:0,max:4294967295})}</div><p>${escape(p.description)}</p><div class="notice blue">Changing the ruleset resets the current Loom and draft only. Historical evidence retains its originally recorded ruleset.</div><div class="control-line" style="margin-top:15px"><button class="button primary" data-action="settings-apply">Apply research parameters</button></div><div class="divider"></div><div class="panel-title">Data management</div><p>Settings and evidence live in this browser's localStorage. No accounts or cloud sync. Import and export JSON backups to move devices.</p><div class="control-line"><button class="button primary" data-action="backup">Download backup</button><button class="button secondary" data-action="restore">Restore backup</button><input type="file" id="backupFile" hidden accept=".json,application/json"><button class="button danger" data-action="reset-all">Clear local data</button></div></section>
 <section class="panel"><div class="panel-title">Canonical knowledge base</div>${[['Weave engine source',SOURCES.repo],['Combat System',SOURCES.combat],['Core Loom Rules',SOURCES.loom],['Balance Constants',SOURCES.balance],['Weaver Design',SOURCES.design]].map(([name,url])=>`<div class="workspace-item"><div class="square">↗</div><div><a href="${url}" target="_blank" rel="noreferrer"><strong>${escape(name)}</strong></a><p>Source material · externally maintained</p></div></div>`).join('')}<div class="notice"><strong>Scope:</strong> this is an independent research suite, not the Weave game. It does not implement complete Traits, online networking, live matchmaking, authoritative server RNG, or exact v0.2 combat replay.</div></section></div>
 <div class="panel" style="margin-top:15px"><div class="panel-title">Research contract</div><div class="info-grid"><div class="info-mini"><small>ENGINE MODES</small><strong>Released v0.1.2 vs v0.2 trial</strong><p>Do not mix stats, formulas or Thread rules silently.</p></div><div class="info-mini"><small>ANALYTICS METHOD</small><strong>Seeded / deterministic</strong><p>Same seeds for comparable experiments; model version included in exports.</p></div><div class="info-mini"><small>BALANCE STATUS</small><strong>Unverified</strong><p>8–10 minutes and all six Rewoven are aspirations, not proof.</p></div><div class="info-mini"><small>CONTENT</small><strong>No character artwork</strong><p>Gameplay-first as requested. Icons and placeholders only.</p></div></div></div>`;}
function render(){renderNav();const content={study:studyPage,compare:comparisonPage,timeline:reportPage,overview,damage,loom:loomPage,draft:draftPage,simulation:simulatorPage,experiments:experimentPage,archive:archivePage,evidence:evidencePage,settings:settingsPage};$('#main').innerHTML=(content[page]||overview)();}
function navigate(id){if(!PAGES.some(x=>x.id===id))return;page=id;history.replaceState(null,'','#'+id);$('#sidebar').classList.remove('open');$('#menuButton').setAttribute('aria-expanded','false');render();window.scrollTo({top:0,behavior:'instant'});}
function setSettings(updates){doc.settings={...doc.settings,...updates};store();render()}
async function workerRun(type,config){if(worker){worker.terminate();worker=null}return new Promise((resolve,reject)=>{try{const workerSource=import.meta.url.startsWith('data:')?'./simulation.worker.mjs':new URL('./simulation.worker.mjs',import.meta.url);const w=new Worker(workerSource,{type:'module'});worker=w;const id=Date.now();const deadline=setTimeout(()=>{w.terminate();worker=null;reject(new Error('Worker execution timed out'))},90000);w.onmessage=event=>{if(event.data?.id!==id)return;clearTimeout(deadline);w.terminate();worker=null;if(event.data.ok)resolve(event.data.payload);else reject(new Error(event.data.error||'Worker error'))};w.onerror=e=>{clearTimeout(deadline);w.terminate();worker=null;reject(new Error(e.message||'Worker failed'))};w.postMessage({id,type,config});}catch(error){reject(error)}})}
async function simulate(type){if(busy)return;const c=simConfig();busy=true;render();toast('Running reproducible synthetic research…');try{const result=await workerRun(type,type==='sensitivity'?{...c,runs:doc.settings.experimentRuns||50}:c);if(type==='sensitivity'){comparison=result;toast('Paired-seed experiment complete')}else{doc.lastBatch=result;store();toast(`${c.runs} synthetic matches analysed`);}}catch(error){toast(error.message,true)}finally{busy=false;render()}}
function updateDamageFromForm(){const a=FORMS.find(x=>x.id===doc.settings.formA);if(a){doc.settings.ap=a.arts.find(x=>x.power)?.power||40;}store();render()}
async function fileText(input,maxBytes=4_000_000){const file=input.files?.[0];if(!file)return null;if(file.size>maxBytes)throw new Error(`File too large: maximum ${Math.round(maxBytes/1e6)} MB`);return file.text()}
function handleAction(action){try{switch(action){
 case 'loom-reset':loom=makeBoard(seed(),preset());loomBank={threads:0,overflow:0,bonuses:0,essence:Object.fromEntries(ASPECTS.map(a=>[a,0]))};selectedCell=null;loomStudy=null;render();break;
 case 'loom-auto':{const {a,b}=pickProductive(loom);const result=performSwap(loom,a,b);applyLoomResult(result);selectedCell=null;render();toast(`Removed ${result.strands} Strands · ${result.threads} Threads${result.bonus?' · Bonus Move':''}`);break}
 case 'loom-export':download(`weave-loom-${seed()}-${loom.step}.json`,JSON.stringify({schema:'weave-lab-loom-v1',ruleset:doc.settings.ruleset,seed:seed(),step:loom.step,board:loom.board,history:loom.history,resourceLedger:loomBank},null,2));break;
 case 'loom-reweave':if(loomBank.threads<loom.rules.threadCost)throw new Error('Not enough Threads');loomBank.threads-=loom.rules.threadCost;render();toast('Synthetic Reweave cost applied to Loom ledger');break;
 case 'loom-study':if(busy)return;busy=true;render();workerRun('loom-study',{seed:seed(),count:100,moves:20,rules:preset(),policy:'balanced'}).then(result=>{loomStudy=result;toast('100-seed Loom study complete')}).catch(e=>toast(e.message,true)).finally(()=>{busy=false;render()});break;
 case 'loom-study-export':if(!loomStudy)throw new Error('Run study first');{const e=addEvidence('loom',{seed:seed(),count:100,model:'loom-only'},loomStudy.metrics);download('weave-loom-seed-study.json',JSON.stringify({evidence:e,study:loomStudy},null,2));render();break}
 case 'draft-reset':draft=newDraft(seed());render();break;
 case 'draft-auto':draft=autofill(draft);render();break;
 case 'draft-to-sim':navigate('simulation');break;
 case 'save-damage':{const x=damageEvidencePayload();addEvidence('damage',x.settings,x.output,'mathematical');toast('Damage evidence saved');render();break}
 case 'export-damage':{const x=damageEvidencePayload();const e=makeEvidence({kind:'damage',...x,ruleset:doc.settings.ruleset,source:'mathematical'});download(`weave-damage-${seed()}.json`,JSON.stringify(e,null,2));break}
 case 'sim-run':simulate('batch');break;
 case 'sim-evidence':if(!doc.lastBatch)throw new Error('Run a batch first');addEvidence('simulation',doc.lastBatch.settings,doc.lastBatch.stats);toast('Seeded batch recorded');render();break;
 case 'sim-json':if(!doc.lastBatch)throw new Error('Run a batch first');download('weave-lab-batch.json',JSON.stringify(doc.lastBatch,null,2));break;
 case 'sim-csv':if(!doc.lastBatch)throw new Error('Run a batch first');download('weave-lab-matches.csv',exportCSV(doc.lastBatch.records,['seed','winner','moves','turns','bonusMoves','reachedMoveCap']),'text/csv');break;
 case 'experiment-run':simulate('sensitivity');break;
 case 'experiment-export':if(!comparison)throw new Error('Run experiment first');{const e=addEvidence('experiment',{seed:seed(),runs:doc.settings.experimentRuns||50},comparison);download('weave-lab-sensitivity.json',JSON.stringify(e,null,2));render();break}
 case 'report-parse':{const text=$('#reportJSON').value;if(text.length>4_000_000)throw new Error('Report too large');importedReport=verifyBattleReport(text);render();toast('Battle Report metadata inspected');break}
 case 'report-file':$('#reportFile').click();break;
 case 'report-evidence':if(!importedReport)throw new Error('No inspected report');addEvidence('report',{seed:importedReport.seed},importedReport,'game-report');toast('Report metadata saved');render();break;
 case 'evidence-all':download('weave-lab-evidence.json',JSON.stringify({schema:'weave-lab-export-v1',records:doc.evidence},null,2));break;
 case 'evidence-csv':download('weave-lab-evidence.csv',exportCSV(doc.evidence.map(x=>({kind:x.kind,ruleset:x.ruleset,recordedAt:x.recordedAt,model:x.model,checksum:x.checksum})),['kind','ruleset','recordedAt','model','checksum']),'text/csv');break;
 case 'settings-apply':{const v=$('#settingsRuleset').value,s=numeric($('#settingsSeed').value,12345,0,4294967295);doc.settings={...doc.settings,ruleset:PRESETS[v]?v:'v0.2',seed:s};store();initializeEngines();render();toast('Research parameters applied');break}
 case 'backup':download('weave-lab-backup.json',JSON.stringify(doc,null,2));break;
 case 'restore':$('#backupFile').click();break;
 case 'reset-all':if(confirm('Clear ALL local Weave Lab research data and evidence? This cannot be undone without a backup.')){clearData();doc=readData();initializeEngines();comparison=null;importedReport=null;render();toast('Local research data cleared')}break;
 default:throw new Error('Unknown action '+action)
 }}catch(error){toast(error.message,true)}}
function damageEvidencePayload(){const cfg=doc.settings,a=FORMS.find(x=>x.id===cfg.formA),b=FORMS.find(x=>x.id===cfg.formB),legacy=cfg.ruleset==='v0.1.2';const def=legacy?cfg.legacyDef:cfg.mode==='physical'?b.phy:b.spe;const inputs={ap:cfg.ap,atk:legacy?cfg.legacyAtk:a.atk,def,shield:cfg.shield,hp:legacy?cfg.legacyHp:b.hp,trueDamage:cfg.trueDamage,immune:!legacy&&b.lineId==='craglet',critical:cfg.critical,constant:cfg.constant,mode:cfg.ruleset};return {settings:{attacker:legacy?'Hypothetical legacy attacker':a.name,target:legacy?'Hypothetical legacy target':b.name,category:cfg.mode,inputs},output:resolveDamage(inputs)}}
function changeValue(target){const v=target.value;switch(target.id){
 case 'damageA':setSettings({formA:v});break;case 'damageB':setSettings({formB:v});break;case 'legacyAtk':case 'legacyDef':case 'legacyHp':setSettings({[target.id]:numeric(v,100,0,9999)});break;case 'damageAP':setSettings({ap:numeric(v,40,0,1000)});break;case 'damageShield':setSettings({shield:numeric(v,0,0,10000)});break;case 'damageType':setSettings({mode:v});break;case 'damageConstant':case 'simConstant':setSettings({constant:numeric(v,50,1,500)});break;case 'damageTrue':setSettings({trueDamage:target.checked});break;case 'damageCrit':setSettings({critical:target.checked});break;
 case 'simSeed':case 'experimentSeed':setSettings({seed:numeric(v,12345,0,4294967295)});initializeEngines();break;
 case 'simRuns':setSettings({simRuns:numeric(v,100,1,1000)});break;case 'policyA':case 'policyB':setSettings({[target.id]:v});break;case 'simAPScale':setSettings({apScale:numeric(v,1,.2,3)});break;case 'experimentRuns':setSettings({experimentRuns:numeric(v,50,10,250)});break;
 case 'archiveAspect':archiveAspect=v;render();break;case 'archiveForm':archiveForm=v;render();break;
 }}
document.addEventListener('click',event=>{
 const nav=event.target.closest('[data-page]');if(nav){navigate(nav.dataset.page);return}
 const action=event.target.closest('[data-action]');if(action){handleAction(action.dataset.action);return}
 const cell=event.target.closest('[data-cell]');if(cell){const i=Number(cell.dataset.cell);if(selectedCell===null||!adjacent(selectedCell,i)){selectedCell=i;render();return}try{const result=performSwap(loom,selectedCell,i);applyLoomResult(result);selectedCell=null;render();toast(`${result.strands} Strands removed${result.bonus?' · Bonus Move':''}`)}catch(e){toast(e.message,true)}return}
 const pick=event.target.closest('[data-pick]');if(pick){try{draft=draftPick(draft,pick.dataset.pick);render()}catch(e){toast(e.message,true)}return}
 const evidence=event.target.closest('[data-evidence]');if(evidence){const record=doc.evidence.find(x=>x.checksum===evidence.dataset.evidence);if(record){download(`weave-evidence-${record.checksum}.json`,JSON.stringify(record,null,2))}return}
});
document.addEventListener('change',async event=>{const t=event.target;
 if(t.id==='ruleset'){doc.settings.ruleset=t.value;store();initializeEngines();render();toast(`${preset().label} selected`);return}
 if(t.id==='reportFile'&&t.files?.length){try{const text=await fileText(t);importedReport=verifyBattleReport(text);render();toast('Report metadata imported')}catch(e){toast(e.message,true)}return}
 if(t.id==='backupFile'&&t.files?.length){try{const text=await fileText(t);const imported=importData(text);if(confirm('Replace local Weave Lab settings and evidence with this backup?')){doc=imported;store();initializeEngines();render();toast('Backup restored')}}catch(e){toast(e.message,true)}return}
 changeValue(t);
});
document.addEventListener('input',event=>{if(event.target.id==='archiveSearch'){const start=event.target.selectionStart;archiveFilter=event.target.value;render();const input=$('#archiveSearch');input.focus();input.setSelectionRange(start,start)}});
$('#menuButton').addEventListener('click',()=>{const sidebar=$('#sidebar');sidebar.classList.toggle('open');$('#menuButton').setAttribute('aria-expanded',String(sidebar.classList.contains('open')))});
const incoming=location.hash.replace('#','');page=PAGES.some(x=>x.id===incoming)?incoming:'overview';window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(id!==page&&PAGES.some(x=>x.id===id))navigate(id)});
connectResearch({render,toast});
render();
if('serviceWorker' in navigator&&location.protocol!=='file:')window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
